for w in wl:
    a=addr(w); bal[a.count('∈')-a.count('∋')]+=1
print("per-word balance (∈ − ∋) over the 2048-symbol alphabet:")
for k in sorted(bal): print(f"   {k:+d}: {bal[k]:5d}  ({100*bal[k]/2048:5.2f}%)")
mean=sum(k*v for k,v in bal.items())/2048
print(f"  mean {mean:+.5f}   → a phrase of 12 has mean {12*mean:+.4f}")
# exact 12-fold convolution over the WHOLE 2048^12 space
dist={0:1.0}
p={k:v/2048 for k,v in bal.items()}
for _ in range(12):
    nd=collections.defaultdict(float)
    for a,pa in dist.items():
        for b,pb in p.items(): nd[a+b]+=pa*pb
    dist=dict(nd)
T=dist.get(0,0.0); B=sum(v for k,v in dist.items() if k>0); F=sum(v for k,v in dist.items() if k<0)
print(f"\nEXACT over all 2048^12 = 2^132 phrases (no sampling):")
print(f"   T  {100*T:6.3f}%      B  {100*B:6.3f}%      F  {100*F:6.3f}%")
print(f"   measured on 10,000 real phrases:   T   9.900%      B  35.400%      F  54.700%")
