            std::path::PathBuf::from("../mOMonadOS/target/x86_64-unknown-linux-gnu/release/momonados"),
            std::path::PathBuf::from(
                concat!(env!("HOME"), "/imsgct/mOMonadOS/target/x86_64-unknown-linux-gnu/release/momonados"),
